// DecodeGetPrescriptionRequest returns a decoder for requests sent to the
// platformKillswitches getPrescription endpoint.
func DecodeGetPrescriptionRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*platformkillswitches.GetPrescriptionPayload, error) {
	return func(r *http.Request) (*platformkillswitches.GetPrescriptionPayload, error) {
		var payload *platformkillswitches.GetPrescriptionPayload
		var (
			organizationID string
			prescriptionID string
			sessionToken   *string
			err            error
		)
		qp := r.URL.Query()
		organizationID = qp.Get("organization_id")
		if organizationID == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("organization_id", "query string"))
		}
		prescriptionID = qp.Get("prescription_id")
		if prescriptionID == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("prescription_id", "query string"))
		}
		err = goa.MergeErrors(err, goa.ValidateFormat("prescription_id", prescriptionID, goa.FormatUUID))
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewGetPrescriptionPayload(organizationID, prescriptionID, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

