// DecodeListPrescriptionsRequest returns a decoder for requests sent to the
// platformKillswitches listPrescriptions endpoint.
func DecodeListPrescriptionsRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*platformkillswitches.ListPrescriptionsPayload, error) {
	return func(r *http.Request) (*platformkillswitches.ListPrescriptionsPayload, error) {
		var payload *platformkillswitches.ListPrescriptionsPayload
		var (
			organizationID string
			limit          *int32
			afterID        *string
			sessionToken   *string
			err            error
		)
		qp := r.URL.Query()
		organizationID = qp.Get("organization_id")
		if organizationID == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("organization_id", "query string"))
		}
		{
			limitRaw := qp.Get("limit")
			if limitRaw != "" {
				v, err2 := strconv.ParseInt(limitRaw, 10, 32)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("limit", limitRaw, "integer"))
				}
				pv := int32(v)
				limit = &pv
			}
		}
		if limit != nil {
			if *limit < 1 {
				err = goa.MergeErrors(err, goa.InvalidRangeError("limit", *limit, 1, true))
			}
		}
		if limit != nil {
			if *limit > 100 {
				err = goa.MergeErrors(err, goa.InvalidRangeError("limit", *limit, 100, false))
			}
		}
		afterIDRaw := qp.Get("after_id")
		if afterIDRaw != "" {
			afterID = &afterIDRaw
		}
		if afterID != nil {
			err = goa.MergeErrors(err, goa.ValidateFormat("after_id", *afterID, goa.FormatUUID))
		}
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewListPrescriptionsPayload(organizationID, limit, afterID, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

